#include <iostream>

class Complex {
public:
    Complex(int re, int im) : re_(re), im_(im) {}
    Complex operator+(const Complex& other) const {
        return Complex(re_ + other.re_, im_ + other.im_);
    }
    int real() const { return re_; }
    int imag() const { return im_; }
private:
    int re_, im_;
};

int main() {
    Complex a(1, 2), b(3, 4);
    Complex c = a + b;
    std::cout << c.real() << " " << c.imag() << "\n";
    return 0;
}

