#include <iostream>
#include <stdexcept>

int divide(int a, int b) {
    if (b == 0) throw std::invalid_argument("division by zero");
    return a / b;
}

int main() {
    try {
        std::cout << divide(10, 2) << "\n";
        std::cout << divide(1, 0) << "\n";
    } catch (const std::exception& e) {
        std::cout << "error: " << e.what() << "\n";
    }
    return 0;
}

#include <iostream>
#include <stdexcept>

class InsufficientFunds : public std::runtime_error {
public:
    explicit InsufficientFunds(int shortfall)
        : std::runtime_error("insufficient funds"), shortfall_(shortfall) {}
    int shortfall() const { return shortfall_; }
private:
    int shortfall_;
};

int main() {
    try {
        throw InsufficientFunds(30);
    } catch (const InsufficientFunds& e) {
        std::cout << e.what() << " " << e.shortfall() << "\n";
    }
    return 0;
}

